/** Returns SVG markup. Unknown names return an empty string. */
function icon( string $name, string $label = '', string $class = '' ): string {
    if ( ! isset( ICONS[ $name ] ) ) {
        return '';
    }
    $a11y = '' === $label ? 'aria-hidden="true" focusable="false"' : 'role="img" aria-label="' . esc_attr( $label ) . '"';
    return sprintf(
        '<svg class="hr-icon hr-icon-%1$s %2$s" xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" %3$s>%4$s</svg>',
        esc_attr( $name ),
        esc_attr( $class ),
        $a11y,
        ICONS[ $name ]
    );
}
